(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory(require('./passive-catalog.js'));else root.MythosStudy=factory(root.MythosPassives);})(typeof globalThis!=='undefined'?globalThis:this,function(T){'use strict';
const validLevel=n=>Number.isInteger(n)&&n>=1&&n<=99;
function budget(level){return level-1;}
function connected(ids){const set=new Set(ids);set.add('root');if([...set].some(id=>!T.index.has(id)))return false;const seen=new Set(['root']),queue=['root'];for(let i=0;i<queue.length;i++)for(const id of T.index.get(queue[i]).neighbors)if(set.has(id)&&!seen.has(id)){seen.add(id);queue.push(id);}return seen.size===set.size;}
function valid(ids,level){return validLevel(level)&&ids instanceof Set&&!ids.has('root')&&ids.size<=budget(level)&&connected(ids);}
function pathTo(ids,target){if(!T.index.has(target)||target==='root'||ids.has(target))return [];const visited=new Set(['root',...ids]),queue=[...visited],parent=new Map();for(let i=0;i<queue.length;i++)for(const id of T.index.get(queue[i]).neighbors){if(visited.has(id))continue;visited.add(id);parent.set(id,queue[i]);if(id===target){const path=[];let at=id;while(!ids.has(at)&&at!=='root'){path.push(at);at=parent.get(at);}return path.reverse();}queue.push(id);}return [];}
function addPath(ids,path,level){if(!valid(ids,level)||!Array.isArray(path)||!path.length||new Set(path).size!==path.length)return null;const candidate=new Set(ids);for(const id of path){const node=T.index.get(id);if(!node||id==='root'||candidate.has(id)||!node.neighbors.some(n=>n==='root'||candidate.has(n)))return null;candidate.add(id);}return valid(candidate,level)?candidate:null;}
function remove(ids,id,level){if(!ids.has(id))return null;const next=new Set(ids);next.delete(id);return valid(next,level)?next:null;}
function totals(ids){const sum={};for(const id of ids){const n=T.index.get(id);if(n)for(const [key,value]of Object.entries(n.mods))sum[key]=(sum[key]||0)+value;}for(const key in sum)sum[key]=Math.round(sum[key]*1000)/1000;return sum;}
function validateSave(raw){if(!raw||raw.version!==1||!validLevel(raw.level)||!Array.isArray(raw.nodes)||raw.nodes.length>98||new Set(raw.nodes).size!==raw.nodes.length||raw.nodes.some(id=>typeof id!=='string'))throw Error('Estudo incompatível ou distribuição inválida.');const ids=new Set(raw.nodes);if(!valid(ids,raw.level))throw Error('Os pontos excedem o nível ou o caminho está desconectado.');return {level:raw.level,nodes:ids};}
function snapshot(level,ids){if(!valid(ids,level))throw Error('Distribuição inválida.');return {version:1,level,nodes:[...ids]};}
function search(query,family='all'){const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR'),q=norm(query.trim());return new Set(T.nodes.filter(n=>n.id!=='root'&&(family==='all'||n.family===family)&&(!q||norm(n.title+' '+(n.group||'')+' '+T.lines(n).join(' ')).includes(q))).map(n=>n.id));}
return {budget,connected,valid,pathTo,addPath,remove,totals,validateSave,snapshot,search};
});
